corrected_code:
const BeeQueue = require('bee-queue');
const backupQueue = new BeeQueue('database-backups', { isWorker: false });

router.get('/api/backups/status/:jobId', verifyToken, async (req, res) => {
  const job = await backupQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Backup job not found' });
  if (job.data.tenantId !== req.user.tenantId && !req.user.isSuperAdmin) {
    return res.status(403).json({ error: 'Access denied: backup job belongs to another tenant' });
  }
  res.json({
    status: job.status,
    progress: job.progress,
    dumpLocation: job.data.backupLocation,
    databaseName: job.data.dbName
  });
});
